import json,pathlib
p=pathlib.Path(__file__).parent
before=json.loads((p/'before-final.json').read_text());after=json.loads((p/'after-final.json').read_text())
bb=json.loads((p/'before-browser.json').read_text());ab=json.loads((p/'after-browser.json').read_text())
data={a['id']:{'poses':[{ 'name':ap['name'],'before':bp['browser'],'after':ap['browser'],'beforeImage':f"/home/dev/terrain-perf-evidence/before-{a['id']}-{ap['name']}.png",'afterImage':f"/home/dev/terrain-perf-evidence/after-{a['id']}-{ap['name']}.png"} for bp,ap in zip(b['poses'],a['poses'])]} for b,a in zip(bb,ab)}
rows=''.join(f"<tr><td>{a['id'].title()}</td><td>{b['bytes']/1e6:.2f} MB</td><td>{a['bytes']/1e6:.2f} MB</td><td>−{100*(1-a['bytes']/b['bytes']):.1f}%</td></tr>"for b,a in zip(before,after))
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font:14px var(--font-sans,system-ui);color:var(--foreground,#222);margin:0}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums;margin:12px 0 20px}th,td{padding:9px 5px;text-align:right;border-bottom:1px solid var(--border,#ddd)}th:first-child,td:first-child{text-align:left}p{line-height:1.5}.muted{color:var(--muted-foreground,#666);font-size:12px}nav{display:flex;gap:6px;flex-wrap:wrap;margin:10px 0}button{font:inherit;color:inherit;background:transparent;border:1px solid var(--border,#aaa);border-radius:7px;padding:7px 12px;cursor:pointer;transition:background .16s,color .16s}button.active{background:var(--foreground,#222);color:var(--background,#fff)}.views{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0}img{width:100%;display:block;border-radius:5px}figcaption{margin:5px 0;color:var(--muted-foreground,#666);font-size:12px}#numbers{font-variant-numeric:tabular-nums}@media(max-width:450px){.views{grid-template-columns:1fr}button{padding:6px 9px}}</style></head><body>
<p><strong>Terrain geometry storage</strong> — all vertex buffers and LOD indices</p><table><thead><tr><th>Map</th><th>Before</th><th>After</th><th>Saved</th></tr></thead><tbody>ROWS</tbody></table>
<nav id="maps" aria-label="Map"></nav><nav id="poses" aria-label="Camera pose"></nav><div class="views"><figure><img id="before" alt="Terrain before optimization"><figcaption>Before</figcaption></figure><figure><img id="after" alt="Terrain after optimization"><figcaption>After</figcaption></figure></div><p id="numbers"></p><p class="muted">Identical 960 × 600 terrain-only diagnostic poses, High LOD preset. Roads and sampled prop tiles retain full detail. Appearance limits keep triangle reductions conservative; extra Uint16 chunks increase some draw-call counts. These are not whole-game FPS measurements.</p>
<script>const data=DATA;let map='riviera',pose=2;const maps=document.getElementById('maps'),poses=document.getElementById('poses');for(const key of Object.keys(data)){const b=document.createElement('button');b.textContent=key[0].toUpperCase()+key.slice(1);b.onclick=()=>{map=key;draw()};maps.appendChild(b)}for(const [i,name]of ['Start line','Mid-route','Overview'].entries()){const b=document.createElement('button');b.textContent=name;b.onclick=()=>{pose=i;draw()};poses.appendChild(b)}function draw(){const p=data[map].poses[pose];document.getElementById('before').src=p.beforeImage;document.getElementById('after').src=p.afterImage;document.getElementById('numbers').textContent=`Triangles: ${p.before.triangles.toLocaleString()} → ${p.after.triangles.toLocaleString()} · Draw calls: ${p.before.calls} → ${p.after.calls}`;[...maps.children].forEach((b,i)=>b.classList.toggle('active',Object.keys(data)[i]===map));[...poses.children].forEach((b,i)=>b.classList.toggle('active',i===pose));}draw();console.log('Validated maps:',Object.keys(data).length,'poses:',Object.values(data).reduce((n,m)=>n+m.poses.length,0));</script></body></html>'''.replace('ROWS',rows).replace('DATA',json.dumps(data))
(p/'comparison.html').write_text(html)
